```javascript
//* Feed
const articlesFeed = async (req, res, next) => {
  try {
    const { loggedUser } = req;
    if (!loggedUser) throw new UnauthorizedError();

    const { limit = 3, offset = 0 } = req.query;
    const authors = (await Follower.find({ "_id.followerId": loggedUser._id }).lean()).map(f => f._id.userId);

    const articles = await Article.find({ authorId: { $in: authors } })
      .sort({ createdAt: -1 })
      .skip(parseInt(offset) * parseInt(limit))
      .limit(parseInt(limit))
      .lean();

    const count = await Article.countDocuments({ authorId: { $in: authors } });

    const result = [];
    for (const article of articles) {
      result.push(await articleResponse(article, loggedUser));
    }

    res.json({ articles: result, articlesCount: count });
  } catch (error) {
    next(error);
  }
};
```
